SELECT i.invoice_id AS invoice_id, i.invoice_no AS invoice_no, i.invoice_date AS invoice_date, i.supplier_id AS supplier_id, i.supplier_name AS supplier_name, i.invoice_amount AS invoice_amount, i.tax_amount AS tax_amount, i.total_amount AS total_amount, GREATEST( IFNULL(i.payment_amount, 0), IFNULL(pay.sum_paid, 0) ) AS payment_amount, IFNULL(i.tax_rate, 0) / 100 AS tax_rate FROM pms_invoice i LEFT JOIN ( SELECT invoice_id, SUM(payment_amount) AS sum_paid FROM pms_invoice_payment WHERE del_flag = '0' GROUP BY invoice_id ) pay ON pay.invoice_id = i.invoice_id WHERE i.invoice_id IN
#{id}
AND i.del_flag = '0'

SELECT pl.customer_id AS customer_id, SUM(r.this_amount) AS received_amount, COUNT(*) AS receipt_count FROM mk_payment_record r JOIN mk_payment_plan pl ON pl.plan_id = r.plan_id WHERE r.confirm_status = '1' AND pl.customer_id IN
#{id}
GROUP BY pl.customer_id
